describe('Touch Targets Accessibility', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
    });

    it('should have touch targets larger than 48x48 pixels', () => {
        cy.get('button, a, input[type="button"], input[type="submit"]').each(($el) => {
            const width = $el.width();
            const height = $el.height();
            expect(width).to.be.greaterThan(48);
            expect(height).to.be.greaterThan(48);
        });
    });

    it('should not have any touch targets smaller than 48x48 pixels', () => {
        cy.get('button, a, input[type="button"], input[type="submit"]').each(($el) => {
            const width = $el.width();
            const height = $el.height();
            expect(width).to.be.greaterThan(0).and.to.be.lessThan(48).or.to.be.greaterThan(48);
            expect(height).to.be.greaterThan(0).and.to.be.lessThan(48).or.to.be.greaterThan(48);
        });
    });
});
